/// `collapse`: a civilisation falls back one age when stability stays below
/// `COLLAPSE_STABILITY_BELOW` for `COLLAPSE_FOR_SECONDS`, or its population drops below
/// `COLLAPSE_POP_SHARE` of the age's entry population.
pub const COLLAPSE_STABILITY_BELOW: f32 = 0.15;
pub const COLLAPSE_FOR_SECONDS: f32 = 30.0;
pub const COLLAPSE_POP_SHARE: f32 = 0.6;

/// `conflict.escalation`, lowest first.
pub const ESCALATION: [&str; 6] = ["scuffle", "feud", "raid", "battle", "war", "civil_war"];
/// War between civilisations needs a declaration from this age (`escalation.war.from`).
pub const WAR_FROM_AGE: u8 = 7;

